import numbers
from typing import List, Literal, Optional

from pydantic import ConfigDict, Field, model_validator

from ray.llm._internal.common.base_pydantic import BaseModelExtended

# Keep in sync with ray.util.placement_group.VALID_PLACEMENT_GROUP_STRATEGIES.
PlacementStrategy = Literal["PACK", "SPREAD", "STRICT_PACK", "STRICT_SPREAD"]


class BundleConfig(BaseModelExtended):
    """Configuration for a single placement group resource bundle.

    ``CPU`` and ``GPU`` are well-known fields. Any additional keyword arguments
    are treated as custom named resources (e.g. ``TPU=4.0``). All resource
    counts are normalized to floats to align with Ray's resource typing, so
    integer inputs (e.g. ``CPU=2``) are coerced to floats in ``model_dump()``.
    """

    # Allow arbitrary extra resource types (e.g. TPU, custom resources).
    model_config = ConfigDict(protected_namespaces=tuple(), extra="allow")

    CPU: float = Field(default=0.0, description="Number of CPUs per bundle")
    GPU: float = Field(default=0.0, description="Number of GPUs per bundle")

    @model_validator(mode="before")
    @classmethod
    def _coerce_and_validate_resources(cls, data):
        # Only process raw mappings; already-constructed instances pass through.
        if not isinstance(data, dict):
            return data

        coerced = {}
        for key, value in data.items():
            if isinstance(value, bool) or not isinstance(value, numbers.Number):
                raise ValueError(
                    f"Resource '{key}' must be a number, got {value!r}."
                )
            float_value = float(value)
            if float_value < 0:
                raise ValueError(
                    f"Resource '{key}' must be non-negative, got {float_value}."
                )
            coerced[key] = float_value
        return coerced


class PlacementGroupConfig(BaseModelExtended):
    """Configuration for a Ray placement group.

    Exactly one of ``bundles`` or ``bundle_per_worker`` must be provided. Raw
    dicts supplied for the bundle fields are automatically coerced into
    :class:`BundleConfig` instances.
    """

    bundles: Optional[List[BundleConfig]] = Field(
        default=None, description="List of resource bundles."
    )
    bundle_per_worker: Optional[BundleConfig] = Field(
        default=None,
        description=(
            "Resource bundle specification for each worker. "
            "Cannot be used together with 'bundles'."
        ),
    )
    strategy: PlacementStrategy = Field(description="Placement group strategy.")

    @model_validator(mode="after")
    def _validate_bundle_options(self):
        if self.bundles is not None and self.bundle_per_worker is not None:
            raise ValueError(
                "Cannot specify both 'bundles' and 'bundle_per_worker'. "
                "Use 'bundle_per_worker' for a simple per-worker resource "
                "specification, or 'bundles' for full control."
            )
        if self.bundles is None and self.bundle_per_worker is None:
            raise ValueError(
                "Must specify either 'bundle_per_worker' or 'bundles'."
            )
        return self
